#include "event_bus.hpp"
#include "event_log.hpp"

#include <cassert>
#include <cstdio>
#include <vector>

static void test_bulk_resubscribe_is_atomic_on_invalid_id() {
    EventLog log(10);
    EventBus bus(log);

    int id1 = bus.subscribe("a", [](const Event&) {});
    int fake_id = id1 + 9999;

    std::vector<int> ids = {id1, fake_id};
    int result = bus.bulkResubscribe(ids, "b");
    assert(result == 0);

    int published = bus.publish("a", "x");
    assert(published == 1);
}

static void test_bulk_resubscribe_respects_destination_capacity() {
    EventLog log(10);
    EventBus bus(log, 1);

    int id1 = bus.subscribe("a", [](const Event&) {});
    int id2 = bus.subscribe("a", [](const Event&) {});
    (void)id2;

    std::vector<int> ids = {id1};
    bus.subscribe("b", [](const Event&) {});
    int result = bus.bulkResubscribe(ids, "b");
    assert(result == 0);
}

int main() {
    test_bulk_resubscribe_is_atomic_on_invalid_id();
    test_bulk_resubscribe_respects_destination_capacity();
    printf("PASS\n");
    return 0;
}

