#pragma once

#include <functional>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

#include "event.hpp"
#include "event_log.hpp"

class EventBus {
public:
    using Callback = std::function<void(const Event&)>;

    explicit EventBus(EventLog& log, int maxSubscribersPerTopic = -1)
        : log_(log), maxSubscribersPerTopic_(maxSubscribersPerTopic) {}

    int countSubscribersForTopic(const std::string& topic) const {
        int count = 0;
        for (const auto& entry : subscribers_) {
            if (entry.second.first == topic) {
                count++;
            }
        }
        return count;
    }

    int subscribe(const std::string& topic, Callback cb) {
        if (maxSubscribersPerTopic_ >= 0 && countSubscribersForTopic(topic) >= maxSubscribersPerTopic_) {
            return -1;
        }
        int id = next_id_++;
        subscribers_[id] = std::make_pair(topic, std::move(cb));
        return id;
    }

    /* Moves an existing subscription to a different topic. Returns 1 on
     * success, 0 if oldId doesn't exist or the target topic is already
     * at capacity (subscription left unchanged). */
    int resubscribe(int oldId, const std::string& newTopic) {
        auto it = subscribers_.find(oldId);
        if (it == subscribers_.end()) {
            return 0;
        }
        if (maxSubscribersPerTopic_ >= 0 && countSubscribersForTopic(newTopic) >= maxSubscribersPerTopic_) {
            return 0;
        }
        it->second.first = newTopic;
        return 1;
    }

    /* Moves a batch of existing subscriptions to `newTopic` in one
     * call. Must be atomic in two ways: (1) validate that EVERY id in
     * `oldIds` currently exists BEFORE moving any of them - one bad id
     * anywhere in the list leaves every subscription exactly where it
     * was; (2) validate the WHOLE batch's combined size against
     * `newTopic`'s maxSubscribersPerTopic (existing subscribers on
     * newTopic + batch size, only counting ids not already on
     * newTopic), again before moving anything. Returns 1 on success. */
    int bulkResubscribe(const std::vector<int>& oldIds, const std::string& newTopic) {
        if (oldIds.empty()) {
            return 0;
        }
        for (int id : oldIds) {
            if (subscribers_.find(id) == subscribers_.end()) {
                return 0;
            }
        }
        if (maxSubscribersPerTopic_ >= 0) {
            int current = countSubscribersForTopic(newTopic);
            int incoming = 0;
            for (int id : oldIds) {
                if (subscribers_[id].first != newTopic) {
                    incoming++;
                }
            }
            if (current + incoming > maxSubscribersPerTopic_) {
                return 0;
            }
        }
        for (int id : oldIds) {
            subscribers_[id].first = newTopic;
        }
        return 1;
    }

    void unsubscribe(int subscription_id) {
        subscribers_.erase(subscription_id);
    }

    int publish(const std::string& topic, const std::string& payload) {
        Event event{next_seq_++, topic, payload};
        log_.record(event);

        int invoked = 0;
        for (const auto& entry : subscribers_) {
            const std::string& sub_topic = entry.second.first;
            const Callback& cb = entry.second.second;
            if (sub_topic == topic) {
                cb(event);
                invoked++;
            }
        }
        return invoked;
    }

private:
    EventLog& log_;
    int maxSubscribersPerTopic_;
    std::unordered_map<int, std::pair<std::string, Callback>> subscribers_;
    int next_id_ = 1;
    long next_seq_ = 1;
};

